UPDATE lessons SET title='Year 4, Week 24, Lesson 1: Artists, sculptors and designers', data=json_patch(data,'{"child_mission":"Sculptors and designers solve 3D problems for different purposes: gallery sculpture, playground forms, product design or public statues. Study published examples to notice materials, scale, audience and site. Describe process evidence (maquettes, joins, finishes) rather than inventing private biographies.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same arts idea to a new artwork or performance, then compare two choices for clarity of effect.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nCompare a small desk sculpture and a public outdoor sculpture with two differences that matter for design.\n\nFEEDBACK\nStrong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.''\n\nWATCH FOR\nAssuming every sculpture is only for museums. Design purposes vary.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nFrom an approved source, study one sculptor or designer’s work. Write materials, purpose, site and one process clue you observe. Credit the source.\n\nWrite a short reflection naming one artistic choice you changed and why. Movement or instrument work is optional, adult-supervised and can be described instead.","interactive_activities":null,"learning_area":"Creative Arts","learning_intention":"Sculptors and designers solve 3D problems for different purposes: gallery sculpture, playground forms, product design or public statues. Study published examples to notice materials, scale, audience and site. Describe process evidence (maquettes, joins, finishes) rather than inventing private biographies.","lesson_number":1,"lesson_role":"Explore and learn","materials":["Paper or typed answer space","Pencil","Optional: scrap paper, crayons, safe classroom instruments or clear movement space with an adult nearby"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["CA2-VIS-01"],"parent_notes":"Parent: Marking guidance for the independent task: From an approved source, study one sculptor or designer’s work. Write materials, purpose, site and one process clue you observe. Credit the source. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: Strong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.'' Reasoning: I used sculptor by attending to designer rather than copying the worked model.\n\nParent: Written model 2: Common error: Assuming every sculpture is only for museums. Design purposes vary. Correction: Strong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.'' Why: the correction restores accurate use of sculptor.\n\nParent: Likely misconception: Assuming every sculpture is only for museums. Design purposes vary. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating sculptor on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with sculptor, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Require independently produced work with a specific supporting detail. / Require misconception + correction + purpose-linked reason..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"Strong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.'' This matches the lesson skill for sculptor.","options":["Strong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.''","Assuming every sculpture is only for museums. Design purposes vary.","Say it looks nice with no element or technique named.","Copy the example artwork or script and call that independent work."],"question":"Compare a small desk sculpture and a public outdoor sculpture with two differences that matter for design. Which response is most accurate?","type":"multiple_choice"},{"correct_index":3,"explanation":"Assuming every sculpture is only for museums. Design purposes vary. That misconception weakens accuracy; the other choices align with the lesson idea.","options":["Sculptors and designers solve 3D problems for different purposes: gallery sculpture, playground forms, product design or public statues. Study published…","Strong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.''","Careful use of designer with clear evidence.","Assuming every sculpture is only for museums. Design purposes vary."],"question":"Which statement is a common mistake when practising sculptor?","type":"multiple_choice"},{"correct_index":1,"explanation":"Understanding is shown by new evidence and named designer, not by copying the model.","options":["Invent a sacred First Nations design without permission or guidance.","Apply the idea with new evidence and name the designer used.","Repeat the worked example wording with no new evidence.","Choose randomly because any option could be right."],"question":"A learner is practising sculptor. Which approach best shows understanding?","type":"multiple_choice"},{"correct_index":1,"explanation":"Strong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.'' uses elements, techniques and audience effect appropriately for this lesson.","options":["Copy the example artwork or script and call that independent work.","Strong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.''","Assuming every sculpture is only for museums. Design purposes vary.","Say it looks nice with no element or technique named."],"question":"Which response best shows careful thinking about sculptor?","type":"multiple_choice"},{"correct_index":1,"explanation":"Strong answers name specific evidence and what it shows.","options":["Assuming every sculpture is only for museums. Design purposes vary.","Name a specific source, cue or example and say what it shows about sculptor.","Make a bigger claim without naming any source or cue.","Copy a classmate’s sentence with no local detail."],"question":"Which habit strengthens evidence about designer?","type":"multiple_choice"},{"correct_index":0,"explanation":"The stronger choice matches the taught idea with concrete detail.","options":["Example: Looking at photos of a public playground sculpture, students note rounded safe edges, bright colour for visibility and bolt…","Assuming every sculpture is only for museums. Design purposes vary.","Invent a sacred First Nations design without permission or guidance.","Say it looks nice with no element or technique named."],"question":"Using this lesson idea — Sculptors and designers solve 3D problems for different purposes: gallery sculpture, playground forms,… — which choice is best?","type":"multiple_choice"},{"correct_index":3,"explanation":"Respect and accuracy mean checking evidence and honouring limits/protocols.","options":["Invent missing details to make the answer sound complete.","Ignore safety or cultural protocols to finish faster.","Treat every online claim as equally reliable.","Check facts/cues, acknowledge limits, and avoid inventing details."],"question":"Which action shows respect and accuracy together?","type":"multiple_choice"},{"correct_index":2,"explanation":"Independence requires a new example that still uses the skill.","options":["Copy the example artwork or script and call that independent work.","Assuming every sculpture is only for museums. Design purposes vary.","From an approved source, study one sculptor or designer’s work. Write materials, purpose, site and one process clue you observe. Credit the source.","Retype the worked example with no new example."],"question":"Which task best shows independent use of sculptor?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Require independently produced work with a specific supporting detail.","question":"Produce a fresh example demonstrating sculptor on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Original response on new material: Strong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.'' Reasoning: I used sculptor by attending to designer rather than copying the worked model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Require misconception + correction + purpose-linked reason.","question":"Name one likely error with sculptor, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Common error: Assuming every sculpture is only for museums. Design purposes vary. Correction: Strong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.'' Why: the correction restores accurate use of sculptor.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent artwork or performance notes and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-arts-y4-w24-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA Creative Arts alignment using catalogue outcome codes (CA2-*); content-point mapping remains pending. First Nations arts content requires local Aboriginal educator or Custodian guidance before acceptance; do not invent sacred designs.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise sculptor.","Read the mission before you start making or performing.","Keep the audience effect of your choice in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reasons with the feedback.","Adjust anything that does not name an effect clearly."],"learn":["Study how the first demonstration is built.","Point to the element or technique that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore elements, safety or respectful practice.","Prefer a named artistic reason over a guess that merely looks colourful."],"submit":["Confirm that your choice and reason are both present.","Proofread element names and safety notes.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked example.","Name one exact element, technique or cue before you decide.","Think through the small prompt before opening the comparison."],"teach1":["Return to the example and list the key artistic choices.","Say what each choice does for the artwork or audience.","A final praise word alone is weaker than a named effect."],"teach2":["Compare a weak choice with a stronger one.","Change the element or technique, not only the decoration.","Name the mistake you are repairing."],"teach3":["Choose a fresh subject or piece that still uses the same skill.","Write one reason in your own words.","Do not retype the worked example as your answer."],"write":["Follow every part of the independent instructions.","Include original work notes and a short reflection.","Save work that shows the skill on new material."]},"subject":"Visual Arts","success_criteria":["I can use sculptor with a specific example from this lesson.","I can identify designer and explain why it matters.","I can practise process independently on a new prompt.","I can notice public artwork needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":2,"explanation":"Sculptors and designers solve 3D problems for different purposes: gallery sculpture, playground forms, product design or public statues. Study published examples to notice materials, scale, audience and site. Describe process evidence (maquettes, joins, finishes) rather than…","options":["An answer copied without understanding.","A guess with no artistic reason.","Sculptors and designers solve 3D problems for different purposes: gallery sculpture, playground forms, product design or public statues. Study published examples to notice materials, scale, audience and site. Describe process evidence (maquettes, joins, finishes) rather than inventing private biographies.","A comment that only says it looks nice with no element named."],"question":"Which choice best shows accurate use of this idea about sculptor?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: Looking at photos of a public playground sculpture, students note rounded safe edges, bright colour for visibility and bolt plates for stability outdoors.\n\nTRY FIRST\nCompare a small desk sculpture and a public outdoor sculpture with two differences that matter for design.\n\nFEEDBACK\nStrong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.''","explain":"Sculptors and designers solve 3D problems for different purposes: gallery sculpture, playground forms, product design or public statues. Study published examples to notice materials, scale, audience and site. Describe process evidence (maquettes, joins, finishes) rather than inventing private biographies.\n\nWHY IT MATTERS\nThis helps the learner make intentional visual, music, drama or dance choices and name their effect, rather than saying an artwork is simply “nice”. Keep every claim linked to an element or technique.\n\nHOW TO WORK\nRead the worked example and name the elements, techniques or performance choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For movement or instruments, use a clear space, ask an adult to be nearby and stop if anything feels unsafe. You may always describe a choice instead of performing it. One deliberate artistic choice with a named effect is more useful than a longer praise sentence.","icon":"📖","notice":"Assuming every sculpture is only for museums. Design purposes vary. Name the element or technique and its effect, not just decoration.","title":"Understand and demonstrate","visual":[{"alt":"Sculptors and designers.","caption":"Purpose shapes form.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Purpose</text><text x=\"28\" y=\"78\">gallery or public</text><text x=\"358\" y=\"42\">Site</text><text x=\"358\" y=\"78\">where it stands</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which artistic choice matters most.","who":"pip"},{"text":"Name the element, technique or performance choice and the effect it creates before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this example: Example: Looking at photos of a public playground sculpture, students note rounded safe edges, bright colour for visibil Then write your own artistic reason.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which artistic choice matters most.\nJuno: Name the element, technique or performance choice and the effect it creates before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this example: Example: Looking at photos of a public playground sculpture, students note rounded safe edges, bright colour for visibil Then write your own artistic reason."}}]},{"check":{"correct_index":3,"explanation":"Make the arts idea visible: name the element, technique or performance choice you used and say what effect it creates. Supported responses name the element or technique and its effect.","options":["A comment that only says it looks nice with no element named.","An answer copied without understanding.","A guess with no artistic reason.","Make the arts idea visible: name the element, technique or performance choice you used and say what effect it creates."],"question":"Which choice best shows accurate use of this idea about sculptor?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: Looking at photos of a public playground sculpture, students note rounded safe edges, bright colour for visibility and bolt plates for stability outdoors. Look at each line, sound, movement or role choice that carries the idea.\n\nTRY FIRST\nList the key artistic choices from the example and say what each one does for the audience or artwork.\n\nFEEDBACK\nThe most useful response names the element or technique and its effect, not only “it looks nice”.","explain":"Make the arts idea visible: name the element, technique or performance choice you used and say what effect it creates.\n\nWHY IT MATTERS\nThis helps the learner make intentional visual, music, drama or dance choices and name their effect, rather than saying an artwork is simply “nice”. Keep every claim linked to an element or technique.\n\nHOW TO WORK\nRead the worked example and name the elements, techniques or performance choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For movement or instruments, use a clear space, ask an adult to be nearby and stop if anything feels unsafe. You may always describe a choice instead of performing it. One deliberate artistic choice with a named effect is more useful than a longer praise sentence.","icon":"📖","notice":"Writing only a final praise word without naming a choice does not show arts thinking. Name the element or technique and its effect, not just decoration.","title":"Show the artistic choice","visual":[{"alt":"Reading process clues.","caption":"Credit the source.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Clues</text><text x=\"28\" y=\"78\">maquette bolts finish</text><text x=\"358\" y=\"42\">Source</text><text x=\"358\" y=\"78\">credit published</text></g></svg>"}]},{"check":{"correct_index":2,"explanation":"Use an intentionally weak or disrespectful arts choice as a comparison. Name the specific error, then show a clearer or more respectful choice. Supported responses name the element or technique and its effect.","options":["An answer copied without understanding.","A guess with no artistic reason.","Use an intentionally weak or disrespectful arts choice as a comparison. Name the specific error, then show a clearer or more respectful choice.","A comment that only says it looks nice with no element named."],"question":"Which choice best shows accurate use of this idea about sculptor?","type":"multiple_choice"},"example":"WORKED MODEL\nAssuming every sculpture is only for museums. Design purposes vary. Here is a more helpful example: Example: Looking at photos of a public playground sculpture, students note rounded safe edges, bright colour for visibility and bolt plates for stability outdoors.\n\nTRY FIRST\nDescribe why the warned-against choice weakens the work, then write a stronger choice with a reason.\n\nFEEDBACK\nStrong answer: ''Outdoor needs weatherproof materials and safer edges; desk piece can be fragile and detailed.''","explain":"Use an intentionally weak or disrespectful arts choice as a comparison. Name the specific error, then show a clearer or more respectful choice.\n\nWHY IT MATTERS\nThis helps the learner make intentional visual, music, drama or dance choices and name their effect, rather than saying an artwork is simply “nice”. Keep every claim linked to an element or technique.\n\nHOW TO WORK\nRead the worked example and name the elements, techniques or performance choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For movement or instruments, use a clear space, ask an adult to be nearby and stop if anything feels unsafe. You may always describe a choice instead of performing it. One deliberate artistic choice with a named effect is more useful than a longer praise sentence.","icon":"📖","notice":"Changing the decoration without changing the artistic idea does not fix the error. Assuming every sculpture is only for museums. Design purposes vary. Name the element or technique and its effect, not just decoration.","title":"Test a misconception"},{"check":{"correct_index":0,"explanation":"Use the same arts idea in a new artwork, song, drama or dance, not a copy of the example. Review clarity, safety and respectful practice. Supported responses name the element or technique and its effect.","options":["Use the same arts idea in a new artwork, song, drama or dance, not a copy of the example. Review clarity, safety and respectful practice.","A comment that only says it looks nice with no element named.","An answer copied without understanding.","A guess with no artistic reason."],"question":"Which choice best shows accurate use of this idea about sculptor?","type":"multiple_choice"},"example":"WORKED MODEL\nSculptors and designers solve 3D problems for different purposes: gallery sculpture, playground forms, product design or public statues. Study published examples to notice materials, scale, audience and site. Describe process evidence (maquettes, joins, finishes) rather than inventing private biographies. Now choose a different subject or piece to show you can transfer the idea.\n\nTRY FIRST\nMake or describe one fresh example that uses the same skill and write a short reason for your main choice.\n\nFEEDBACK\nThe new example should use the same arts idea as the model, but with different content or material.","explain":"Use the same arts idea in a new artwork, song, drama or dance, not a copy of the example. Review clarity, safety and respectful practice.\n\nWHY IT MATTERS\nThis helps the learner make intentional visual, music, drama or dance choices and name their effect, rather than saying an artwork is simply “nice”. Keep every claim linked to an element or technique.\n\nHOW TO WORK\nRead the worked example and name the elements, techniques or performance choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For movement or instruments, use a clear space, ask an adult to be nearby and stop if anything feels unsafe. You may always describe a choice instead of performing it. One deliberate artistic choice with a named effect is more useful than a longer praise sentence.","icon":"📖","notice":"Repeating the worked example cannot show transfer to a new artwork or performance. Name the element or technique and its effect, not just decoration.","title":"Transfer to a new artwork or performance"}],"title":"Year 4, Week 24, Lesson 1: Artists, sculptors and designers","unit_number":5,"unit_title":"Sculpture and 3D forms","week":24,"week_in_unit":4,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample: Looking at photos of a public playground sculpture, students note rounded safe edges, bright colour for visibility and bolt plates for stability outdoors.\n\nWrite what makes this example effective, naming the element, technique or performance choice and its effect.","worked_visuals":[{"alt":"Sculptors and designers.","caption":"Purpose shapes form.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Purpose</text><text x=\"28\" y=\"78\">gallery or public</text><text x=\"358\" y=\"42\">Site</text><text x=\"358\" y=\"78\">where it stands</text></g></svg>"},{"alt":"Reading process clues.","caption":"Credit the source.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Clues</text><text x=\"28\" y=\"78\">maquette bolts finish</text><text x=\"358\" y=\"42\">Source</text><text x=\"358\" y=\"78\">credit published</text></g></svg>"}],"year_level":"Year 4"}') WHERE seed_key='s2-arts-y4-w24-l1' AND family_id IS NULL;
